WITH UserBadges AS (SELECT U.Id AS UserId, COUNT(B.Id) AS BadgeCount, GROUP_CONCAT(B.Name, ', ') AS BadgeNames FROM Users AS U LEFT JOIN Badges AS B ON U.Id = B.UserId GROUP BY U.Id), UserPostStats AS (SELECT P.OwnerUserId, COUNT(P.Id) AS PostCount, SUM(CASE WHEN P.PostTypeId = 1 THEN 1 ELSE 0 END) AS QuestionCount, SUM(CASE WHEN P.PostTypeId = 2 THEN 1 ELSE 0 END) AS AnswerCount, SUM(CASE WHEN P.PostTypeId IN (0, 4, 5) THEN 1 ELSE 0 END) AS WikiCount FROM Posts AS P GROUP BY P.OwnerUserId), RankedUsers AS (SELECT U.Id, COALESCE(BadgeCount, 0) AS BadgeCount, COALESCE(PostCount, 0) AS PostCount, USERPOSTSTATS.QuestionCount, USERPOSTSTATS.AnswerCount, USERPOSTSTATS.WikiCount, RANK() OVER (ORDER BY COALESCE(BadgeCount, 0) DESC NULLS FIRST, COALESCE(PostCount, 0) DESC NULLS FIRST) AS UserRank FROM Users AS U LEFT JOIN UserBadges AS UB ON U.Id = UB.UserId LEFT JOIN UserPostStats AS USERPOSTSTATS ON U.Id = USERPOSTSTATS.OwnerUserId) SELECT U.DisplayName, R.UserRank, R.BadgeCount, R.PostCount, R.QuestionCount, R.AnswerCount, R.WikiCount FROM RankedUsers AS R JOIN Users AS U ON R.Id = U.Id WHERE R.UserRank <= 10 AND R.BadgeCount > 0 ORDER BY R.UserRank